        PlayerCompanionData data;
        if (data.setTeamAutoJoin(target, teamIndex, !(data = CompanionDataService.data(player)).teamAutoJoin(target, teamIndex))) {
            CompanionDataService.save(player, data);
        }
        CompanionTeamService.syncToClient(player);
    }

    public static void deleteTeam(ServerPlayer player, CompanionTeamTarget target, int teamIndex) {
        PlayerCompanionData data = CompanionDataService.data(player);
        if (data.deleteTeam(target, teamIndex)) {
            CompanionDataService.save(player, data);
        }
        CompanionTeamService.syncToClient(player);
    }

    public static void setTeam(ServerPlayer player, CompanionTeamTarget target, int teamIndex, List<UUID> uuids) {
        PlayerCompanionData data = CompanionDataService.data(player);
        if (target == null || teamIndex < 0 || teamIndex >= data.teamCount(target)) {
            CompanionTeamService.syncToClient(player);
            return;
        }
        Optional<UUID> locked = CompanionTeamService.firstBusy(player, data, uuids);
        if (locked.isPresent()) {
            FindMeDebugLogger.lifecycle("TEAM_SET_REJECTED_LOCKED", player, locked.get(), null, CompanionLifecycleFacade.busyReason(player, data, locked.get()), "TEAM", "team:set", data.storedEntity(locked.get()).isPresent(), false);
