            FindMeDefaultSettingsService.copyBoolean(json, tag, "friendlyFireProtection");
            FindMeDefaultSettingsService.copyBoolean(json, tag, "boundCreatureBlockProtection");
            FindMeDefaultSettingsService.copyBoolean(json, tag, "autoStoreOnBinding");
            FindMeDefaultSettingsService.copyBoolean(json, tag, "autoOrganizeTeams");
            FindMeDefaultSettingsService.copyBoolean(json, tag, "fallingAnimation");
            FindMeDefaultSettingsService.copyInt(json, tag, "guiOpacityPercent");
            return FindMeUiSettings.load(tag);
        }
        catch (IOException | RuntimeException exception) {
            FindMeMod.LOGGER.warn("Could not read FindMe UI defaults from {}", (Object)UI_DEFAULTS, (Object)exception);
