        if (!Files.isRegularFile(source, new LinkOption[0])) {
            source = FMLPaths.CONFIGDIR.get().resolve("find_me-server.toml");
        }
        Path destination = FMLPaths.GAMEDIR.get().resolve("defaultconfigs/find_me-server.toml");
