            throw new IOException("Current world server config was not found: " + String.valueOf(source));
        }
        Files.createDirectories(destination.getParent(), new FileAttribute[0]);
        Path temporary = destination.resolveSibling(String.valueOf(destination.getFileName()) + ".tmp");
        Files.copy(source, temporary, StandardCopyOption.REPLACE_EXISTING);
        FindMeDefaultSettingsService.moveAtomic(temporary, destination);
    }

