package com.kuzhi.findme.server.ui;

import com.kuzhi.findme.FindMeMod;
import com.kuzhi.findme.common.FindMeSettingsAction;
import com.kuzhi.findme.common.FindMeUiSettings;
import com.kuzhi.findme.network.FindMeSettingsPacket;
import com.kuzhi.findme.network.ModNetwork;
import com.kuzhi.findme.server.data.CompanionDataService;
import com.kuzhi.findme.server.data.PlayerCompanionData;
import com.kuzhi.findme.server.module.FindMeModuleService;
import com.kuzhi.findme.server.ui.CompanionTeamService;
import com.kuzhi.findme.server.ui.FindMeDefaultSettingsService;
import com.kuzhi.findme.server.ui.FindMeSettingsDefaultsPolicy;
import java.io.IOException;
import net.minecraft.server.level.ServerPlayer;

public final class FindMeSettingsService {
    private FindMeSettingsService() {
    }

    public static void sync(ServerPlayer player) {
        FindMeSettingsService.send(player, false);
    }

    public static void handle(ServerPlayer player, FindMeSettingsAction action, FindMeUiSettings settings) {
        if (action == FindMeSettingsAction.SAVE) {
            FindMeSettingsService.save(player, settings);
        } else if (action == FindMeSettingsAction.EXPORT_DEFAULTS) {
            FindMeSettingsService.exportDefaults(player, settings);
        } else if (action == FindMeSettingsAction.RESET_DEFAULTS) {
            FindMeSettingsService.resetDefaults(player);
        } else if (action == FindMeSettingsAction.RESET_BINDING_HISTORY) {
            PlayerCompanionData data = CompanionDataService.data(player);
            data.resetBindingCinematicHistory();
            CompanionDataService.save(player, data);
            FindMeSettingsService.send(player, true);
        } else {
            FindMeSettingsService.sync(player);
            FindMeModuleService.sync(player);
        }
    }

    private static void exportDefaults(ServerPlayer player, FindMeUiSettings settings) {
        if (!FindMeSettingsService.canManageDefaults(player)) {
            ModNetwork.sendToPlayer(player, new FindMeSettingsPacket(FindMeSettingsAction.UPDATE, CompanionDataService.data(player).uiSettings(), false, "Creative mode and operator permission are required."));
            return;
        }
        try {
            PlayerCompanionData data = CompanionDataService.data(player);
            data.setUiSettings(settings);
            data.organizeTeams();
            CompanionDataService.save(player, data);
            FindMeDefaultSettingsService.export(player.m_20194_(), settings);
            ModNetwork.sendToPlayer(player, new FindMeSettingsPacket(FindMeSettingsAction.UPDATE, data.uiSettings(), true, "New-world defaults exported."));
            CompanionTeamService.syncToClient(player);
        }
        catch (IOException exception) {
            FindMeMod.LOGGER.error("Could not export FindMe defaults", (Throwable)exception);
            ModNetwork.sendToPlayer(player, new FindMeSettingsPacket(FindMeSettingsAction.UPDATE, CompanionDataService.data(player).uiSettings(), false, "Could not export defaults."));
        }
    }

    private static void resetDefaults(ServerPlayer player) {
        FindMeUiSettings reset = FindMeSettingsDefaultsPolicy.resetTarget(FindMeSettingsService.canManageDefaults(player), FindMeDefaultSettingsService.loadUiDefaults());
        PlayerCompanionData data = CompanionDataService.data(player);
        data.setUiSettings(reset);
        data.organizeTeams();
        CompanionDataService.save(player, data);
        ModNetwork.sendToPlayer(player, new FindMeSettingsPacket(FindMeSettingsAction.UPDATE, data.uiSettings(), true, "Settings reset."));
        CompanionTeamService.syncToClient(player);
    }

    static boolean canManageDefaults(ServerPlayer player) {
        return player != null && FindMeSettingsDefaultsPolicy.canManageDefaults(player.m_20310_(2), player.m_7500_());
    }

    public static void save(ServerPlayer player, FindMeUiSettings settings) {
        PlayerCompanionData data = CompanionDataService.data(player);
        data.setUiSettings(settings);
        data.organizeTeams();
        CompanionDataService.save(player, data);
        FindMeSettingsService.send(player, true);
        CompanionTeamService.syncToClient(player);
    }

    private static void send(ServerPlayer player, boolean saved) {
        PlayerCompanionData data = CompanionDataService.data(player);
        ModNetwork.sendToPlayer(player, new FindMeSettingsPacket(FindMeSettingsAction.UPDATE, data.uiSettings(), true, saved ? "Settings saved." : "Settings synced."));
    }
}

