public static boolean handleRosterAction(ServerPlayer player, MountRosterAction action, UUID targetUuid) {
    if (ExternalVehicleBridge.available()) {
        VehicleCommandAction translated = switch (action) {
            default -> throw new IncompatibleClassChangeError();
            case MountRosterAction.SELECT -> VehicleCommandAction.SELECT;
            case MountRosterAction.ACTIVATE -> VehicleCommandAction.SELECT_SUMMON;
            case MountRosterAction.RECALL -> VehicleCommandAction.RECALL;
        };
        boolean result = ExternalVehicleBridge.command(player, translated, targetUuid, -1);
        if (ExternalVehicleBridge.available()) {
            return result;
        }
    }
    PlayerCompanionData data = CompanionDataService.data(player);
    if (action == null || targetUuid == null || !data.containsVehicle(targetUuid)) {
        return false;
    }
    if (VehicleManager.rejectBusy(player, data, targetUuid, "vehicle:merged_roster_" + action.name().toLowerCase())) {
        VehicleManager.syncToClient(player);
        return false;
    }
    boolean accepted = switch (action) {
        default -> throw new IncompatibleClassChangeError();
        case MountRosterAction.SELECT -> {
            VehicleManager.cancelPendingSummons(player.m_20148_());
            boolean selected = data.setActiveVehicleUuid(targetUuid);
            if (selected) {
                CompanionDataService.save(player, data);
            }
            yield selected;
        }
        case MountRosterAction.ACTIVATE -> {
            if (!data.setActiveVehicleUuid(targetUuid)) {
                yield false;
            }
            CompanionDataService.save(player, data);
            yield CompanionLifecycleFacade.summonOrStoreActiveVehicle(player, data, "vehicle:merged_roster_activate");
        }
        case MountRosterAction.RECALL -> CompanionLifecycleFacade.recallVehicleUuid(player, data, targetUuid, "vehicle:merged_roster_recall");
    };
    VehicleManager.syncToClient(player);
    return accepted;
}

