public static void cancelRosterActivation(ServerPlayer player, UUID targetUuid, String reason) {
    if (player == null) {
        return;
    }
    VehicleManager.cancelPendingSummons(player.m_20148_());
    VehicleCinematicService.cancelForPlayer(player, "mount_roster:" + reason);
    if (targetUuid == null) {
        return;
    }
    PlayerCompanionData data = CompanionDataService.data(player);
    if (VehicleManager.isRideReady(player, data, targetUuid) || !data.containsVehicle(targetUuid)) {
        return;
    }
    if (data.isVehicleDeployed(targetUuid) || data.storedEntity(targetUuid).isEmpty()) {
        VehicleManager.recallUuid(player, data, targetUuid);
        VehicleManager.syncToClient(player);
    }
}

