private static boolean restoreSourceRideAfterFailedRetirement(ServerPlayer player, PlayerCompanionData data, RideHandoffService.Source source) {
    if (source == null || !source.present() || source.type() == RideHandoffService.SourceType.OTHER) {
        return true;
    }
    boolean restored = switch (source.type()) {
        default -> throw new IncompatibleClassChangeError();
        case RideHandoffService.SourceType.FINDME_MOUNT, RideHandoffService.SourceType.ENTITY_VEHICLE -> VehicleCompatibilityService.restorePreviousRide(player, source.entity());
        case RideHandoffService.SourceType.NONE, RideHandoffService.SourceType.OTHER -> true;
    };
    FindMeDebugLogger.info("ride-handoff", "phase=SOURCE_RIDE_ROLLBACK player={} sourceType={} source={} result={}", new Object[]{player.m_20148_(), source.type(), source.uuid(), restored});
    return restored;
}

public static void syncToClient(ServerPlayer player) {
    if (ExternalVehicleBridge.available() && ExternalVehicleBridge.sendRoster(player)) {
        return;
    }
    PlayerCompanionData data = CompanionDataService.data(player);
    List<VehicleListPacket.Entry> wheelEntries = VehicleManager.entries(player, data, data.vehicleWheelOrder());
    List<VehicleListPacket.Entry> allEntries = VehicleManager.entries(player, data, data.vehicleList());
    FindMeDebugLogger.info("vehicle-roster", "phase=SYNC player={} revision={} vehicles={} wheel={} warehouse={} activeIndex={}", player.m_20148_(), CompanionDataService.revision(player), allEntries.size(), wheelEntries.size(), data.vehicleWarehouseOrder().size(), data.activeVehicleIndex());
    ModNetwork.sendToPlayer(player, new VehicleListPacket(CompanionDataService.revision(player), data.activeVehicleIndex(), wheelEntries, allEntries));
}

